openai-sdk-js-ts-9.value:
import OpenAI from "openai";

const client = new OpenAI({ baseURL: "https://dicompute.ai/openai/v1", apiKey: "YOUR_API_KEY" });

const stream = await client.chat.completions.create({
  messages: [{ role: "user", content: "hello" }],
  stream: true,
});
for await (const chunk of stream) {
  process.stdout.write(chunk.choices[0]?.delta?.content ?? "");
}

vercel-ai-sdk-10.value:
import { createOpenAI } from "@ai-sdk/openai";
import { streamText } from "ai";

const dico = createOpenAI({ baseURL: "https://dicompute.ai/openai/v1", apiKey: "YOUR_API_KEY" });

const { textStream } = streamText({
  model: dico.chat("your-model-id"),
  messages: [{ role: "user", content: "hello" }],
});
for await (const delta of textStream) process.stdout.write(delta);

